=== ORIGIN HELP ===
{
    "service": "configurable public test origin \u2014 request capture + canned responses",
    "overview": "A small programmable HTTP endpoint the target can reach. It records every inbound request (the capture log) and returns responses you configure
 with ordered rules. Use it as an out-of-band listener/responder while probing the target \u2014 e.g. to observe callbacks for blind findings, or to control wha
t the target receives when it processes a URL you supply. Configuration only: no code execution, and response bodies are fixed presets (you cannot serve arbitra
ry bytes or set arbitrary headers).",
    "auth": "Every /_admin/* endpoint requires the header X-Admin-Token.",
    "endpoints": {
        "POST /_admin/rules": "Install {\"rules\": [ <rule>, ... ]} (1..32, ordered). Replaces the current rules and clears per-link visit history. Returns {ok,
 count}, or 400 {error} naming the first invalid field.",
        "GET /_admin/requests": "The capture log: every inbound request as {method, path, http_version, headers, status, ts}, oldest first.",
        "POST /_admin/reset": "Clear the rules, the capture log, and all visit history.",
        "GET /_admin/help": "This manual."
    },
    "rule": {
        "shape": {
            "when": "conditions that must all hold",
            "reply": "the response to send"
        },
        "evaluation": "Rules are tried in order; the first rule whose `when` matches is used. If no rule matches, a `page` body is served.",
        "when": {
            "path": "string; matches when the request path starts with this prefix. Omit to match any path.",
            "visit": "\"new\" or \"repeat\". Distinguishes the first request (\"new\") from a later request (\"repeat\") to the SAME issued unique link (see `un
ique`). A path that is not an issued unique link has no visit history and only ever matches \"new\"."
        },
        "reply": {
            "body": "serve a fixed preset document (the only key). One of: page (text/html), feed (application/rss+xml), note (text/plain), clip (video/mp4). Pr
eset bytes and content types are fixed by the service.",
            "status+location": "reply with an HTTP status (one of 301,302,303,307,308; default 302) and a Location header equal to `location` (a relative path o
r an http(s) URL, up to 2048 chars). No other response header can be set.",
            "note": "A reply is EITHER `body` OR `status`/`location`, never both."
        },
        "unique": "If a `location` value contains the literal substring {unique}, the service substitutes a fresh random one-time path on each response (an inte
raction link). Only such issued links carry visit history for `when.visit`.",
        "fixed": "Preset bodies and the /catalog/* resources are service-owned and cannot be altered or re-pointed by rules."
    },
    "limits": {
        "max_rules": 32,
        "max_admin_body_bytes": 65536,
        "max_location_chars": 2048
    },
    "examples": [
        {
            "title": "Serve a page for every request",
            "rules": [
                {
                    "when": {},
                    "reply": {
                        "body": "page"
                    }
                }
            ]
        },
        {
            "title": "Forward one public path to another (public to public)",
            "rules": [
                {
                    "when": {
                        "path": "/go"
                    },
                    "reply": {
                        "status": 302,
                        "location": "/landing"
                    }
                },
                {
                    "when": {
                        "path": "/landing"
                    },
                    "reply": {
                        "body": "note"
                    }
                }
            ]
        },
        {
            "title": "Issue a fresh unique interaction link and serve it",
            "rules": [
                {
                    "when": {
                        "path": "/start"
                    },
                    "reply": {
                        "status": 302,
                        "location": "/i/{unique}"
                    }
                },
                {
                    "when": {
                        "path": "/i/"
                    },
                    "reply": {
                        "body": "page"
                    }
                }
            ]
        },
        {
            "title": "Serve an issued unique link differently on its first vs a repeat visit",
            "rules": [
                {
                    "when": {
                        "path": "/start"
                    },
                    "reply": {
                        "status": 302,
                        "location": "/i/{unique}"
                    }
                },
                {
                    "when": {
                        "path": "/i/",
                        "visit": "new"
                    },
                    "reply": {
                        "body": "page"
                    }
                },
                {
                    "when": {
                        "path": "/i/",
                        "visit": "repeat"
                    },
                    "reply": {
                        "body": "note"
                    }
                }
            ]
        }
    ]
}
